{
  "families": [
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.5,
      "why": "Only a 1-result/cycle family can plausibly reach 250 MSPS on Artix-7; pipelined is the canonical such architecture. Its N+2 latency and one-register-per-rotation structure give the cleanest area/accuracy trade-off. Ranges cover the accuracy threshold (W and N large enough for ~13 bits) down to the smallest W/N that might still pass, so the low-LUT corner is reachable."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 8, "choices": null}
      ],
      "budget_share": 0.5,
      "why": "Also 1 result/cycle, so it can meet 250 MSPS, but registers every m stages instead of every stage. This trades Fmax (longer combinational path) against FF count, and is the most likely source of a lower-LUT / lower-area design on the front. The extra m dimension is worth half the budget because it can shift the Pareto front in ways pipelined cannot."
    }
  ],
  "rationale": "Throughput >= 250 MSPS is the binding architectural constraint: iterative (N+3 cycles/result) and unrolled_k (ceil(N/k)+3 cycles/result) would need Fmax in the GHz range even at their most aggressive settings, which is not attainable on Artix-7, so they are excluded from the first round rather than wasting budget confirming infeasibility. That leaves the two 1-result/cycle families, pipelined and pipelined_m, which are the only ones that can plausibly satisfy the throughput constraint. Accuracy (max_abs_err <= 2^-13) depends only on data_width, n_iter, angle_guard, frac_guard and rounding, so both families are given identical accuracy-parameter ranges wide enough to bracket the 13-bit threshold from below (small W/N, cheap) to comfortably above (larger W/N, safe). The 50/50 split lets round 1 compare the two register-scheduling strategies head-to-head; subsequent rounds can reallocate toward whichever family actually populates the feasible front and can extend ranges if the front sits at a boundary."
}

{
  "decision": "map_front",
  "rationale": "The feasible front is pipelined-only, and that is structural, not a sampling artefact: pipelined/pipelined_m are the only 1-result/cycle families, and pipelined_m already shows 0 feasible with max throughput 171 < 250. iterative (N+3 cycles/result) and unrolled_k (ceil(N/k)+3 cycles/result) would need Fmax of ~1000+ MHz to reach 250 MSPS, so adding them would burn budget on families that cannot satisfy the throughput constraint. Meanwhile the current front is under-mapped on both objective axes relative to the HV reference: luts only reach 2098 vs ref 4000, and accuracy_bits top out at 18.9 while pipelined has already demonstrated 22.76 bits. That leaves a large unclaimed HV region at higher luts/higher accuracy. Spend this round letting NSGA-II map the full pipelined ranges (data_width 8..28, n_iter 4..30, angle_guard -2..4, frac_guard 0..4, both roundings) seeded with the current 22-design front, so the whole trade-off curve — including the high-accuracy end and any lower-LUT corner near the 250 MSPS / 2^-13 boundary — is covered before the final min-luts selection.",
  "next_plan": null
}
